mat_highlight.vertex:
#version 100

precision highp float;
attribute vec4 a_Color;
attribute vec2 a_TextureCoordinate,a_TextureCoordinate1;
attribute vec3 a_Position;
uniform mat4 u_MVPMatrix;
uniform float consumption_value,bar_pos;
varying vec2 uv;
varying mediump float birth,lying;

void main(void) {

	uv = a_TextureCoordinate;
	float tlmask = a_Color.r;

	vec3 p = a_Position;

		//mediump float little_step = step(1.1, bar_pos); //222 79
		//p.x += (clamp(bar_pos, 0., 1.) * 222.) + (little_step * (bar_pos - 1.) * 79.);	

		p.z -= tlmask * (295.* (1.-consumption_value));
	gl_Position = u_MVPMatrix * vec4(p, 1.);

	// -- FS handovers
	birth = smoothstep(0.05, 0.2, consumption_value);
	lying = a_TextureCoordinate1.s;
}

mat_highlight.fragment:
#version 100

precision mediump float;
uniform sampler2D tex0;
uniform float opacity;
varying vec2 uv;
varying float birth,lying;

#define CO vec3(.9,.95,1.)

void main(void) {

	vec4 smpl = texture2D(tex0,uv);
	float alphamask = birth * mix(smpl.b,smpl.g,lying);

	vec4 shd = vec4(CO, alphamask);
	gl_FragColor = shd;	
	gl_FragColor.a *= opacity;
}

mat_bar_backdrop.vertex:
#version 100
precision highp float;

attribute vec2 a_TextureCoordinate;
attribute vec3 a_Position;

uniform mat4 u_MVPMatrix;
uniform float consumption_value,bar_pos,eco,comfort,sport,is_factory; // edrive = eco

varying vec3 mixed_co;
varying vec2 uvCoord;
varying mediump float size_adj,pre_alpha,v_is_factory;

#define DEFAULT vec3(0.,0.,0.)
#define ECO vec3(0.,.45,.9) 
#define COMFORT vec3(.59,.68,.75)
#define SPORT vec3(1.,0.29,0.)
#define FACTORY vec3(1.,1.,1.)

void main(void) {

	// -- texture coordinates	
	uvCoord = a_TextureCoordinate;
	uvCoord.y += mix(1.,0.02,consumption_value);


	// -- color mixin
	mediump float is_default = 1.- clamp(eco + comfort + sport + is_factory, 0., 1.);
	mixed_co = (DEFAULT * is_default) + (ECO * eco) + (COMFORT * comfort) + ((SPORT + 0.1) * sport);
	float satur = 0.4;
	mixed_co = mix(vec3(0.8,0.8,0.8), mixed_co, satur);
	mixed_co = mix(mixed_co, vec3(1.,1.,1.), is_factory);

	gl_Position = u_MVPMatrix * vec4(a_Position, 1.);

	// -- FS handovers
	size_adj = mix(0.9, 0., consumption_value);
	pre_alpha = 0.2 * clamp(consumption_value + 0.2, 0.,1.);
	v_is_factory = is_factory;
}

mat_bar_backdrop.fragment:
#version 100

precision mediump float;

uniform sampler2D tex0;
uniform float opacity;

varying vec3 mixed_co;
varying vec2 uvCoord;
varying float size_adj,pre_alpha,v_is_factory;

void main(void) {

		// -- prepare gradient for different sizes
		vec2 uv = uvCoord;
		uv.y = smoothstep(size_adj, 1., uvCoord.y);

	vec4 smpl = texture2D(tex0, uv);
	float alphamask = mix(smpl.g, smpl.b, v_is_factory) * pre_alpha;

	vec4 shd = vec4(mixed_co, alphamask);

	gl_FragColor = shd;
	gl_FragColor.a *= opacity;	
}

