mat_bar.vertex:
#version 100
precision highp float;

attribute vec4 a_Color;
attribute vec2 a_TextureCoordinate;
attribute vec3 a_Position;

uniform mat4 u_MVPMatrix;
uniform float consumption_value,eco,comfort,sport,bar_pos,is_factory;

varying mediump vec2 varCoord,paintCoord;
varying mediump vec3 mixed_co,mixed_hl,pack_look;
varying mediump float pre_alpha,v_consumption_value,bump;


#define DEFAULT vec3(1.,1.,1.) * 0.6
#define ECO vec3(0.,.5, 1.) // edrive = eco
#define COMFORT vec3(.57,.68,.7) * 0.8
#define SPORT vec3(1.,0.29,0.)
#define FACTORY vec3(1.,1.,1.)

#define HL_DEFAULT vec3(.7,.7,.7) * 0.6
#define HL_ECO vec3(.3,.6,0.8)
#define HL_COMFORT vec3(.65,.69,.7) * 0.9
#define HL_SPORT vec3(1.,0.5,0.2)
#define HL_FACTORY vec3(1.,1.,1.)


void main(void){

	// -- texture coordinates
	varCoord = a_TextureCoordinate;
		// -- growth
		varCoord.y += mix(0.965,0.007,consumption_value);

	paintCoord = a_TextureCoordinate;
		paintCoord.y -= smoothstep(-3.,10.,consumption_value);

	// -- mix color
	float is_default = 1. - clamp(eco + comfort + sport + is_factory, 0., 1.);
	mixed_co = (DEFAULT * is_default) + (ECO * eco) + (COMFORT * comfort) + ((SPORT + 0.1) * sport);
	mixed_hl = (HL_DEFAULT * is_default) + (HL_ECO * eco) + (HL_COMFORT * comfort) + (HL_SPORT * sport);
	//mixed_hl = mix(mixed_co, vec3(1.,1.,1.), 0.2);

	#ifdef IS_FACTORY
		mixed_co = mix(mixed_co, FACTORY, is_factory);
		mixed_hl = mix(mixed_co, HL_FACTORY, is_factory);
	#endif


	// -- bar pos
	//vec3 p = a_Position;
	//	float little_step = step(1.1, bar_pos); //222 79
	//	p.x += (clamp(bar_pos, 0., 1.) * 222.) + (little_step * (bar_pos - 1.) * 79.);	
	gl_Position = u_MVPMatrix * vec4(a_Position, 1.);


	// -- FS handovers
	pre_alpha = 1.;
	pre_alpha *= a_Color.b; // antialiasing

	v_consumption_value = consumption_value;
	bump = a_TextureCoordinate.y;


	// -- pack em
	float fade = a_TextureCoordinate.t * mix(4.,1.,consumption_value); // top top bottom
	fade += 0.19;
	float lightbow_fade = (1.-a_TextureCoordinate.t) * 3. - mix(2.5, 1., consumption_value);  // bottom to top
	float lightfake_end = 1.-consumption_value;
	pack_look = vec3(fade, lightbow_fade, lightfake_end);
}

mat_bar.fragment:
#version 100
precision mediump float;

uniform sampler2D tex0,tex1;
uniform float opacity;
varying mediump vec2 varCoord,paintCoord;
varying mediump vec3 mixed_co,mixed_hl,pack_look;
varying float pre_alpha,v_consumption_value,bump;

void main(void){


	// -- samples
	vec4 smpl = texture2D(tex0, varCoord);
	vec4 smpl_paint = texture2D(tex1, paintCoord);


		// -- toolbox
		float glowing_edges = smpl.r * 0.8;	// kante oben
		float ant_top_left_right = smpl.b;
		float lightfake_msk = mix(smpl_paint.b, pack_look.x, pack_look.z);
		float lightbow = (smpl_paint.r * clamp(pack_look.y, 0., 1.));
		float outlines = smpl.g;
		float birth = smoothstep(0.01, 0.05, v_consumption_value);

		#ifdef IS_FACTORY
			float bump2 = smoothstep(0., v_consumption_value, bump);
			float center = smoothstep(0.,0.5, bump2) * smoothstep(1.,0.5, bump2);
			outlines += center * smoothstep(0.3, 1., smpl.g);  // add to outlines
		#endif


	// -- color mixin
	float comsk = outlines * lightfake_msk;
	comsk *= mix(1.,2.,lightbow);
	vec3 co = mix(mixed_co, mixed_hl, lightbow) + glowing_edges;
	// -- alphamask
	float alphamsk = ant_top_left_right * pre_alpha;
	alphamsk += glowing_edges;
	alphamsk *= birth;

	vec4 shd = vec4(co * comsk, alphamsk);

	gl_FragColor = shd;
	gl_FragColor.a *= opacity;

	// checker
	//gl_FragColor = smpl_paint;
}

