mat_bg_refl.vertex:
#version 100
#define IS_REFL
precision highp float ;

attribute vec2 a_TextureCoordinate,a_TextureCoordinate1;
attribute vec3 a_Position;

uniform mat4 u_MVPMatrix;
uniform float average_consumption,fade_pos,fade_squeeze; 

varying mediump vec2 varCoord,antCoord;
varying mediump vec2 msk_fade; // x:msk y:fade

void main(void) {

	varCoord = a_TextureCoordinate1.st; // 0-0.5-1
	antCoord = a_TextureCoordinate.st; // ant chords 0-1-0

	msk_fade.x = (1.-a_TextureCoordinate.t) * 80.; // second value being smoothness of edge
	msk_fade.x += mix(-79.,-1.,average_consumption);

	varCoord.y *= 21.;
	antCoord.x *= 3.;

	//FadeOut right
	float softness = fade_squeeze;                                                                               
	float fade_x = (fade_pos - softness) + (softness * fade_pos);
	msk_fade.y = ((1.-varCoord.x) * softness) + fade_x;

	gl_Position = u_MVPMatrix * vec4(a_Position, 1.);
}

mat_bg_refl.fragment:
