	vec4 smpl = texture2D(tex0,varCoord);
	vec4 smpl_ant = texture2D(tex1,antCoord);

	float ant = smpl_ant.b;
	vec4 shd = vec4(CO * smpl.b, clamp(msk_fade.x, 0.,1.) * ant);


	gl_FragColor = shd;
	gl_FragColor.a *= opacity * clamp(msk_fade.y,0.,1.);
}

